type Cmd<T extends Command['type']> = Extract<Command, { type: T }>;

const TITLE_MAX = 80;
const TIP_MAX = 300;
const NOTE_MAX = 300;
const CARD_MAX = 600;

export function challengeTitle(ctx: EngineContext, challenge: ChildChallenge): string {
  return findTemplate(ctx.catalog, challenge.templateId)?.titleChild ?? challenge.customTitle ?? '';
}

function newChallenge(
  tx: Tx,
  ctx: EngineContext,
  fields: Pick<ChildChallenge, 'childId' | 'templateId' | 'customTitle' | 'customIcon' | 'customTip' | 'branch' | 'source' | 'repeatable' | 'status'>,
): ChildChallenge {
  return {
    id: ctx.newId(),
    familyId: tx.state.family.id,
    sparks: 0,
    lastSparkDay: null,
    repeatCount: 0,
    createdAt: ctx.now,
    activatedAt: fields.status === 'active' ? ctx.now : null,
    requestedAt: null,
    completedAt: null,
    ...fields,
  };
}

export function activateTemplate(tx: Tx, cmd: Cmd<'activateTemplate'>, ctx: EngineContext): HandlerResult {
  const { state } = tx;
  if (!state.children.some((c) => c.id === cmd.childId)) return fail('not_found', 'child');
  const template = findTemplate(ctx.catalog, cmd.templateId);
  if (!template) return fail('not_found', 'template');
  if (template.isPlus && !familyLimits(state).fullLibrary) return fail('plus_required');
  const duplicate = state.challenges.some(
    (c) => c.childId === cmd.childId && c.templateId === template.id && c.status !== 'archived',
  );
  if (duplicate) return fail('already_exists');
  if (activeCount(state, cmd.childId) >= state.family.settings.maxActiveChallenges) {
    return fail('max_active_reached');
  }
  const challenge = newChallenge(tx, ctx, {
    childId: cmd.childId,
    templateId: template.id,
    customTitle: null,
    customIcon: null,
    customTip: null,
    branch: template.branch,
    source: 'library',
    repeatable: template.repeatable,
    status: 'active',
  });
  return patchState(tx, { challenges: [...state.challenges, challenge] });
}

export function addCustomChallenge(tx: Tx, cmd: Cmd<'addCustomChallenge'>, ctx: EngineContext): HandlerResult {
  const { state } = tx;
  if (!state.children.some((c) => c.id === cmd.childId)) return fail('not_found', 'child');
  const title = cleanText(cmd.title, TITLE_MAX);
  const icon = cleanIcon(cmd.icon);
  const tip = optionalText(cmd.tip, TIP_MAX);
  if (!title || !icon || tip === undefined || !isBranch(cmd.branch)) return fail('invalid_input');
  if (activeCount(state, cmd.childId) >= state.family.settings.maxActiveChallenges) {
    return fail('max_active_reached');
  }
  const challenge = newChallenge(tx, ctx, {
    childId: cmd.childId,
    templateId: null,
    customTitle: title,
    customIcon: icon,
    customTip: tip,
    branch: cmd.branch,
    source: 'custom',
    repeatable: cmd.repeatable === true,
    status: 'active',
  });
  return patchState(tx, { challenges: [...state.challenges, challenge] });
}

export function setChallengeStatus(tx: Tx, cmd: Cmd<'setChallengeStatus'>, ctx: EngineContext): HandlerResult {
  const challenge = findChallenge(tx.state, cmd.challengeId);
  if (!challenge) return fail('not_found');
  if (challenge.status === 'completed' && cmd.status !== 'archived') return fail('invalid_status');
  if (cmd.status === 'active') {
    if (challenge.status === 'active' || challenge.status === 'requested') return tx;
    if (activeCount(tx.state, challenge.childId) >= tx.state.family.settings.maxActiveChallenges) {
      return fail('max_active_reached');
    }
  }
  return patchState(tx, {
    challenges: replaceById(tx.state.challenges, challenge.id, {
      status: cmd.status,
      requestedAt: cmd.status === 'active' ? challenge.requestedAt : null,
      activatedAt: cmd.status === 'active' ? (challenge.activatedAt ?? ctx.now) : challenge.activatedAt,
    }),
  });
}

/** Shared spark logic for "Jag försökte!" and the parent's "Ge en gnista". */
function addSpark(tx: Tx, ctx: EngineContext, challenge: ChildChallenge, source: AttemptSource): Tx {
  const day = dayKey(ctx.now, tx.state.family.settings.timeZone);
  // One child spark per day, and never for a day before the latest one: day keys
  // (YYYY-MM-DD) sort as strings, so lastSparkDay can only move forward.
  const limited = source === 'child' && challenge.lastSparkDay !== null && challenge.lastSparkDay >= day;
  const hadSparkBefore = tx.state.attempts.some((a) => a.childId === challenge.childId && a.sparkAwarded);

  const attempt: Attempt = {
    id: ctx.newId(),
    familyId: tx.state.family.id,
    childId: challenge.childId,
    childChallengeId: challenge.id,
    source,
    day,
    sparkAwarded: !limited,
    createdAt: ctx.now,
  };
  let result = patchState(tx, { attempts: [...tx.state.attempts, attempt] });
  if (limited) {
    return emit(result, { type: 'spark_already_today', childId: challenge.childId, challengeId: challenge.id });
  }

  const sparks = challenge.sparks + 1;
  result = patchState(result, {
    challenges: replaceById(result.state.challenges, challenge.id, {
      sparks,
      lastSparkDay: source === 'child' ? day : challenge.lastSparkDay,
    }),
  });
  result = emit(result, { type: 'spark_added', childId: challenge.childId, challengeId: challenge.id, sparks });

  const child = result.state.children.find((c) => c.id === challenge.childId);
  if (!child) return result;
  if (!hadSparkBefore) {
    result = unlockSpecial(result, ctx, child.id, child.world, { type: 'first_spark' }, { celebrate: true }).tx;
  }
  if (result.state.family.settings.sparkBonusEnabled && sparks % SPARKS_PER_BONUS_STAR === 0) {
    result = awardStar(result, ctx, {
      childId: child.id,
      reason: 'spark_bonus',
      refId: challenge.id,
      branch: challenge.branch,
      world: child.world,
    });
    result = emit(result, { type: 'bonus_star', childId: child.id, challengeId: challenge.id });
    result = celebrate(result, ctx, child.id, 'bonus_star', { challengeId: challenge.id });
  }
  return result;
}

export function recordAttempt(tx: Tx, cmd: Cmd<'recordAttempt'>, ctx: EngineContext): HandlerResult {
  const challenge = findChallenge(tx.state, cmd.challengeId);
  if (!challenge) return fail('not_found');
  if (challenge.status !== 'active') return fail('invalid_status');
  return addSpark(tx, ctx, challenge, 'child');
}

export function giveSpark(tx: Tx, cmd: Cmd<'giveSpark'>, ctx: EngineContext): HandlerResult {
  const challenge = findChallenge(tx.state, cmd.challengeId);
  if (!challenge) return fail('not_found');
  if (challenge.status !== 'active' && challenge.status !== 'requested') return fail('invalid_status');
  // "Bra försök, nästan där!" sends a requested challenge back to the child's active eggs.
  const reopened =
    challenge.status === 'requested'
      ? patchState(tx, {
          challenges: replaceById(tx.state.challenges, challenge.id, { status: 'active', requestedAt: null }),
        })
      : tx;
  const current = findChallenge(reopened.state, challenge.id) ?? challenge;
  return addSpark(reopened, ctx, current, 'parent');
}

export function requestCompletion(tx: Tx, cmd: Cmd<'requestCompletion'>, ctx: EngineContext): HandlerResult {
  const challenge = findChallenge(tx.state, cmd.challengeId);
  if (!challenge) return fail('not_found');
  if (challenge.status === 'requested') return fail('already_requested');
  if (challenge.status !== 'active') return fail('invalid_status');
  const result = patchState(tx, {
    challenges: replaceById(tx.state.challenges, challenge.id, { status: 'requested', requestedAt: ctx.now }),
  });
  return emit(result, { type: 'completion_requested', childId: challenge.childId, challengeId: challenge.id });
}

/**
 * Approve (or directly register) a completed challenge: +1 star, hatch the next
 * creature of the branch, create the collector card (spec 3.1 and 6.3).
 */
export function approveCompletion(tx: Tx, cmd: Cmd<'approveCompletion'>, ctx: EngineContext, parentId: string | null): HandlerResult {
  const challenge = findChallenge(tx.state, cmd.challengeId);
  if (!challenge) return fail('not_found');
  if (challenge.status !== 'active' && challenge.status !== 'requested') return fail('invalid_status');
  const child = tx.state.children.find((c) => c.id === challenge.childId);
  if (!child) return fail('not_found', 'child');
  const note = optionalText(cmd.note, NOTE_MAX);
  if (note === undefined) return fail('invalid_input');

  const isFirst = !tx.state.completions.some((c) => c.childChallengeId === challenge.id);
  const attemptsCount = tx.state.attempts.filter((a) => a.childChallengeId === challenge.id).length;
  const providedText = optionalText(cmd.cardText, CARD_MAX);
  const cardText =
    providedText ??
    templateCardText({
      firstName: child.firstName,
      title: challengeTitle(ctx, challenge),
      attempts: attemptsCount,
      branch: challenge.branch,
      seed: challenge.id,
    });

  let result = tx;
  let creatureId: string | null = null;
  if (isFirst) {
    const hatched = hatchNext(result, ctx, child.id, child.world, challenge.branch);
    result = hatched.tx;
    creatureId = hatched.creatureId;
  }

  const completion: Completion = {
    id: ctx.newId(),
    familyId: tx.state.family.id,
    childId: child.id,
    childChallengeId: challenge.id,
    approvedBy: parentId,
    approvedAt: ctx.now,
    parentNote: note,
    cardText,
    creatureId,
    world: child.world,
    branch: challenge.branch,
    isFirst,
    attemptsCount,
  };
  result = patchState(result, {
    completions: [...result.state.completions, completion],
    challenges: replaceById(
      result.state.challenges,
      challenge.id,
      challenge.repeatable
        ? { status: 'active', requestedAt: null, repeatCount: challenge.repeatCount + 1, completedAt: ctx.now }
        : { status: 'completed', completedAt: ctx.now },
    ),
  });

  // The celebration comes before the star so the child sees "hatch" before "evolve/milestone".
  result = celebrate(result, ctx, child.id, creatureId ? 'hatch' : 'grow', {
    completionId: completion.id,
    challengeId: challenge.id,
    creatureId,
    branch: challenge.branch,
  });
  result = awardStar(result, ctx, {
    childId: child.id,
    reason: 'completion',
    refId: completion.id,
    branch: challenge.branch,
    world: child.world,
  });
  return emit(result, {
    type: 'challenge_completed',
    childId: child.id,
    challengeId: challenge.id,
    completionId: completion.id,
  });
}
